<script lang="ts">
 import type {EntityView} from '../../bindings';import type {CaseOperations} from './controller.svelte';
 import EntityPicker from '../pickers/EntityPicker.svelte';import EvidencePicker from '../pickers/EvidencePicker.svelte';
 let {operations,route,entity,legacy=false,oninspect}:{operations:CaseOperations;route:{kind:string;id:string}|null;entity:EntityView|null;legacy?:boolean;oninspect:(kind:string,id:string)=>void}=$props();
</script>
      <form onsubmit={operations.write}>
        {#if legacy}<label>Action<select bind:value={operations.action} onchange={()=>operations.mergeConfirmed=false}><option value="create_entity">Create entity</option><option value="add_identifier">Add identifier</option><option value="relate">Create relationship</option><option value="assess">Assess selected subject</option><option value="merge">Merge entities</option><option value="reject">Reject a merge</option><option value="split">Split a merged record</option></select></label>{/if}
        {#if operations.action==="create_entity"}<label>Name<input required bind:value={operations.name}/></label><label>Type<select bind:value={operations.type}>{#each operations.types as [key,label]}<option value={key}>{label}</option>{/each}</select></label><label>Notes<textarea bind:value={operations.notes}></textarea></label>{/if}
        {#if ["add_identifier","relate","merge","reject","split"].includes(operations.action)}
          {#if !legacy}<EntityPicker label="Choose first record" onchoose={record=>{operations.left=record.id;if(!operations.entityChoices.some(r=>r.id===record.id))operations.entityChoices=[...operations.entityChoices,record];}}/>{#if ['relate','merge','reject'].includes(operations.action)}<EntityPicker label="Choose second record" onchoose={record=>{operations.right=record.id;if(!operations.entityChoices.some(r=>r.id===record.id))operations.entityChoices=[...operations.entityChoices,record];}}/>{/if}<p>First record: {operations.entityChoices.find(r=>r.id===operations.left)?.name??operations.left??'None'}. Second: {operations.entityChoices.find(r=>r.id===operations.right)?.name??operations.right??'None'}.</p>{/if}
          <details open={legacy||operations.action==='split'}><summary>Advanced record selectors</summary><label>Find entities<input bind:value={operations.entityQuery} placeholder="Search names to narrow the choices"/></label><button type="button" onclick={operations.findEntities}>Find entities</button><p>Showing up to 50 matches; refine the name to find another entity.</p>
          <label>{operations.action==="split"?"Merged record to separate":"Entity"}<select required bind:value={operations.left}><option value="">Choose an entity</option>{#each (operations.action==="split" && entity ? entity.merged_from.map(e=>({id:e.entity_id,name:e.display_name})):operations.entityChoices) as e}<option value={e.id}>{e.name}</option>{/each}</select></label>
          {#if operations.action==="split" && route?.kind==="entity"}<p>Open the canonical entity first, then choose one of its merged records above.</p>{/if}
          {#if ["relate","merge","reject"].includes(operations.action)}<label>Other entity<select required bind:value={operations.right}><option value="">Choose another entity</option>{#each operations.entityChoices as e}<option value={e.id}>{e.name}</option>{/each}</select></label>{/if}</details>
        {/if}
        {#if operations.action==="add_identifier"}<label>Identifier kind<input required bind:value={operations.namespace}/></label><label>Value<input required bind:value={operations.value}/></label>{/if}
        {#if operations.action==="relate"}<label>Relationship<input required bind:value={operations.relation}/></label>{/if}
        {#if ["create_entity","add_identifier","relate","add_evidence"].includes(operations.action)}
          <fieldset><legend>Evidence citations</legend>{#if !legacy}<EvidencePicker {oninspect} onchoose={citation=>{if(!operations.citations.some(c=>c.id===citation.id&&c.kind===citation.kind&&c.role===citation.role))operations.citations=[...operations.citations,citation];}}/>{/if}<details open={legacy}><summary>Advanced evidence references</summary><p>Open an observation and choose “Use as evidence”, or enter a stored evidence reference.</p><label>Evidence kind<select bind:value={operations.evidenceKind}><option value="observation">Observation</option><option value="artifact">Document</option><option value="capture">Capture</option></select></label><label>Evidence reference<input bind:value={operations.evidenceId}/></label><label>Role<select bind:value={operations.role}><option value="supports">Supports</option><option value="contradicts">Contradicts</option><option value="context">Context</option></select></label><button type="button" onclick={operations.addCitation}>Add citation</button></details>{#each operations.citations as citation,i}<p>{citation.role}: {citation.kind} {citation.id} <button type="button" onclick={()=>operations.citations=operations.citations.filter((_,j)=>i!==j)}>Remove</button></p>{/each}</fieldset>
        {/if}
        {#if operations.action==="assess"}
          <p>Assessing {route?.kind??"nothing selected"}{operations.targetLabel?': '+operations.targetLabel:''}. Open an entity, identifier, or relationship first.</p><label>Dimension<select bind:value={operations.dimension} onchange={()=>operations.assessedValue=""}>{#each operations.scales as scale}<option value={scale.dimension}>{scale.title}</option>{/each}</select></label><label>Judgment<select required bind:value={operations.assessedValue}><option value="">Choose a judgment</option>{#each operations.scales.find(s=>s.dimension===operations.dimension)?.values??[] as [key,label]}<option value={key}>{label}</option>{/each}</select></label>
        {/if}
        {#if ["assess","merge","reject","split"].includes(operations.action)}<label>Reason / contributing factors<textarea required bind:value={operations.reason}></textarea></label>{/if}
        {#if operations.action==="merge"}<button type="button" disabled={!operations.left||!operations.right||operations.left===operations.right||operations.busy} onclick={operations.previewMerge}>Preview merge</button><aside>
          {#if operations.preview}{#each operations.preview as candidate}<p><strong>{candidate.display_name}</strong>: {candidate.merged_from.length+1} records, {candidate.evidence.length} evidence links, {candidate.identifiers.length} identifiers. Review its evidence and individual confidence dimensions before merging.</p>{/each}{/if}<p>Merging combines the two clusters in lists and search. Evidence and conflicting assessments remain on their original records. The older cluster is canonical; a split can separate a record later.</p><label class="check"><input type="checkbox" bind:checked={operations.mergeConfirmed}/>I reviewed the two entities and want to merge them</label></aside>{/if}
        <button disabled={operations.busy||(operations.action==="merge"&&(!operations.mergeConfirmed||!operations.preview))||(operations.action==="assess"&&!["entity","identifier","relationship"].includes(route?.kind??""))}>Record decision</button>
      </form>
<style>form,label{display:grid;gap:8px}form{gap:16px;margin-top:16px}fieldset{min-width:0;border:1px solid var(--border);padding:16px}textarea{min-height:80px;resize:vertical}.check{display:flex;align-items:center}p{overflow-wrap:anywhere}</style>
